import re
from collections import Counter, defaultdict
D='/Users/ivanyakovlev/Documents/GitHub/materials/_studio/zhurnal/2026-07-30_dovodka-fabriki/'
sk=defaultdict(list); zag={}
for l in open(D+'skelet-vladelca.tsv',encoding='utf-8').read().splitlines():
    if not l.startswith('V'): continue
    f=l.split('\t'); sk[f[2].strip()].append(f[0]); zag[f[0]]=f[2]
vd={}
for l in open(D+'verdikt-vladelca.tsv',encoding='utf-8').read().splitlines():
    if not l.startswith('V'): continue
    f=l.split('\t'); vd[f[0]]=f[1]
t=open(D+'KRATNOST-vladelca.md',encoding='utf-8').read()
gname={}; gids=defaultdict(list); memb={}
for b in re.split(r'^### ',t,flags=re.M)[1:]:
    head=b.split('\n')[0]; num=int(head.split('.')[0]); gname[num]=head
    for z in re.findall(r'^- \*\*(.+?)\*\* — `',b,re.M):
        for vid in sk.get(z.strip(),[]):
            gids[num].append(vid)
            if 'V0346'<=vid<='V0690': memb[vid]=num
gmain={}
for g,ids in gids.items():
    c=Counter(vd[i] for i in ids if i in vd)
    if c: gmain[g]=c.most_common(1)[0][0]
by=defaultdict(list)
for v,g in memb.items():
    if vd[v]!=gmain.get(g): by[g].append(v)
for g in sorted(by, key=lambda g:-len(by[g])):
    print(f"\n### гр.{gname[g]}  [главный ярус: {gmain.get(g)}] — отклонилось {len(by[g])} моих")
    for v in sorted(by[g]):
        print(f"   {v} → {vd[v]:11s} | {zag[v][:88]}")
PY
